# Let me trace through the BFS level by level to debug
start_node = "9bf31c7ff0"

print("Level 0:", [start_node])

# Level 1
level1 = graph.get(start_node, [])
print("Level 1:", sorted(level1))

# Level 2
level2 = []
for node in level1:
    for neighbor in graph.get(node, []):
        if neighbor not in level1 and neighbor != start_node:
            level2.append(neighbor)
level2 = list(set(level2))
print("Level 2:", sorted(level2))

# Level 3
level3 = []
for node in level2:
    for neighbor in graph.get(node, []):
        if neighbor not in level2 and neighbor not in level1 and neighbor != start_node:
            level3.append(neighbor)
level3 = list(set(level3))
print("Level 3:", sorted(level3))

# Level 4
level4 = []
for node in level3:
    for neighbor in graph.get(node, []):
        if neighbor not in level3 and neighbor not in level2 and neighbor not in level1 and neighbor != start_node:
            level4.append(neighbor)
level4 = list(set(level4))
print("Level 4:", sorted(level4))
